{"tool":"write","path":"tests/test_export_csv.py","content":""""Focused tests for reports.export.export_csv."""

import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic_order_and_header(self):
        rows = [{"a": 1, "b": 2}, {"a": 3, "b": 4}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n1,2\r\n3,4\r\n")

    def test_rfc4180_quoting(self):
        rows = [{"a": 'x,"y"\nz', "b": "plain"}]
        self.assertEqual(
            export_csv(rows, ["a", "b"]),
            'a,b\r\n"x,""y"\nz",plain\r\n',
        )

    def test_missing_and_none_become_empty(self):
        rows = [{"a": None}, {"b": "v"}]
        self.assertEqual(export_csv(rows, ["a", "b"]), "a,b\r\n,\r\n,v\r\n")

    def test_ignores_unselected_fields(self):
        self.assertEqual(export_csv([{"a": 1, "z": 9}], ["a"]), "a\r\n1\r\n")

    def test_one_shot_generators(self):
        rows = ({"a": i} for i in range(2))
        cols = (c for c in ["a"])
        self.assertEqual(export_csv(rows, cols), "a\r\n0\r\n1\r\n")

    def test_empty_rows_and_empty_columns(self):
        self.assertEqual(export_csv([], ["a"]), "a\r\n")
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])

    def test_unicode_preserved(self):
        self.assertEqual(
            export_csv([{"a": "héllo \u2603"}], ["a"]),
            "a\r\nhéllo \u2603\r\n",
        )

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
    unittest.main()
